import{_ as s,l as i,o as e,c as n,v as t,p as l,x as r,d as E,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"版本控制与变更","description":"","frontmatter":{"title":"版本控制与变更","date":"2026-09-10T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/vcs-changeset.md","filePath":"cs/vcs-changeset.md","lastUpdated":1789023840000}'),p={name:"cs/vcs-changeset.md"};function h(A,a,B,_,u,m){const o=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="版本控制与变更" tabindex="-1">版本控制与变更 <a class="header-anchor" href="#版本控制与变更" aria-label="Permalink to &quot;版本控制与变更&quot;">​</a></h1><div class="epigraph"><p>版本库记录的是快照之间的差分：谁改了接口、谁改了测试、能否回到上一份仍能编译的树。</p><footer>—— 据 Kernighan, Software Tools；ISO/IEC 9899 对分别编译程序的模型整理</footer></div><p>上一课<a href="/cs/test-as-spec">测试作为规格</a>把契约写成可执行例子。本课不重讲断言，也不从托管平台产品另起。缺口是：头文件、实现、测试会一起变，<strong>怎样让一次改动可命名、可回放、可与别人的改动合并</strong>，而不靠邮件里的「最新版.c」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>分别编译已经允许多人改不同翻译单元，但磁盘上的文件没有历史。覆盖保存会丢掉「哪一次把错误码语义改了」。缺口因此不是 <code>git</code> 的子命令表，而是<strong>变更作为对象</strong>：一组文件从旧快照到新快照的差，应当能说明它改了哪条契约。测试红了，要能指出是这次差引起的，而不是「机器上有人改过什么」。</p><p>本课用变更集直觉：提交是带说明的快照；分支是平行的变更线；合并是把两条线的差同时应用到公共祖先上。冲突发生在同一文本区被两边改了——头文件正是最容易冲突的契约面。工具链细节留给后课构建与动态链接；这里只要历史能服务接口。</p><h3 id="版本库不是备份盘" tabindex="-1">版本库不是备份盘 <a class="header-anchor" href="#版本库不是备份盘" aria-label="Permalink to &quot;版本库不是备份盘&quot;">​</a></h3><p>备份保证副本存在；版本控制保证能回答「这一行何时以何种说明进入主干」。把仓库当网盘、提交信息写「update」，历史就无法解释失败码为何改变。也不要把未通过测试的树提交成「先存一下」——上一课刚把测试变成规格，变更应当在规格仍可执行时打点。</p><p><span class="marginnote">Kernighan 的工具传统强调可组合的文本处理；版本控制把文本差分变成协作协议。ISO C 不规定 VCS，但分别编译的程序恰好以文件为变更粒度。本课不绑定某一种托管网站。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>一次变更集应围绕一条理由：修复失败路径、扩展接口、或重构实现而不改契约。头文件与测试同提交，避免「实现已改、调用方还在旧规格上绿」。二进制产物不进历史；源、测试、构建说明进历史。回放：取出旧快照应当仍能按当时的构建步骤编译——这要求构建说明本身也被版本管理，下一课构建系统会接上。不要把生成的 <code>.o</code> 与手写源混进同一份差里，否则别人无法从源复现该快照。</p>',11)),(e(),l(d,null,{default:r(()=>[c(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20OLD%5B%22%E6%97%A7%E5%BF%AB%E7%85%A7%22%5D%20--%3E%20DIFF%5B%22%E5%8F%98%E6%9B%B4%E9%9B%86%EF%BC%9A%E6%8E%A5%E5%8F%A3%E4%B8%8E%E6%B5%8B%E8%AF%95%22%5D%0A%20%20DIFF%20--%3E%20NEW%5B%22%E6%96%B0%E5%BF%AB%E7%85%A7%22%5D%0A%20%20NEW%20--%3E%20TEST%5B%22%E5%86%8D%E8%B7%91%E5%8F%AF%E6%89%A7%E8%A1%8C%E8%A7%84%E6%A0%BC%22%5D%0A%20%20TEST%20--%3E%20OK%5B%22%E7%BB%BF%EF%BC%9A%E5%A5%91%E7%BA%A6%E4%B8%8E%E5%AE%9E%E7%8E%B0%E4%B8%80%E8%87%B4%22%5D%0A%20%20TEST%20--%3E%20BAD%5B%22%E7%BA%A2%EF%BC%9A%E5%B7%AE%E7%A0%B4%E5%9D%8F%E4%BA%86%E8%A7%84%E6%A0%BC%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>合并时优先读冲突的头文件：那是跨单元契约。实现文件冲突次之。生成代码若可从源再生，不要与源双轨进库。</p><p>冲突不是文本事故，是两份契约同时改了同一声明。解决时应先读测试：哪一边的后置条件被留下，哪一边被丢。把两边函数体各留一半、头文件随便拼，链接或许成功，规格已经裂开。标签与发布对应「这一快照可构建且测试绿」，而不是「作者觉得差不多了」。后课封装会限制哪些符号允许出现在公开头文件的差里，历史才不会把内部改名也当成接口变更。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有了变更对象，回归可以定位到一次差，而不是「最近几周」。接口演进变得可见：删掉一个符号会在差里出现，调用方可以在合并时看见。这与第一课的链接对应：符号的添加与删除是程序边界的历史。后课封装会把「哪些符号本不该出现在差的公开面」说成不变量；版本历史是检查公开面漂移的证据。</p><p>分别编译让变更粒度天然是文件，但一次差应当仍围绕一条接口理由：否则审查者只看见一堆 <code>.c</code>，无法判断失败码语义有没有变。头文件进差时，默认假定 ABI 或契约变了，调用方与测试必须同动。生成的目标文件与核心转储不要进库，它们依赖机器，破坏回放。构建说明、编译选项与测试命令是回放的配方，与源同级。后课封装会要求某些文件根本不出现在公开头文件的差里——那是公开面，不是「所有改过的源」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲变基与托管权限，不把 Git 内部对象模型当主干。下一课<a href="/cs/encapsulation-invariant">封装与不变量</a>把「对外可见的差」收得更小。后课默认：源与测试一起成变更集；一次差对应一条理由；头文件冲突等于契约冲突。公开符号的增删应当能在说明里被搜索到，否则接口演进只存在于作者记忆里。构建配方与测试命令不进历史，回放就会变成「在我机器上能编」。</p><p>一次差的说明要写原因，不写文件清单：清单从图里能看见，原因在历史里才能搜到。把「WIP」提交进主干等于让回放点带红测试，规格暂时失效。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>变更集是可命名的快照差，用来解释契约何时改变。</li><li>测试与头文件跟实现同提交，历史才能回放规格。</li><li>版本库回答「为何变成这样」，备份只回答「有没有副本」。</li><li>头文件冲突按契约来解决，不能各留一半函数体。</li><li>下一课限制哪些状态允许出现在公开变更里。</li><li>出处：分别编译的文件模型（ISO C）；Kernighan 对文本工具与程序结构的传统。</li></ul>',10))])}const S=s(p,[["render",h]]);export{T as __pageData,S as default};
